
CREATE SCHEMA "public";
CREATE TABLE "books" (
	"copies" integer NOT NULL,
	"price" double precision NOT NULL,
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "books_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"description" varchar(512),
	"author" varchar(255) NOT NULL,
	"genre" varchar(255),
	"title" varchar(255) NOT NULL,
	CONSTRAINT "books_copies_check" CHECK ((copies >= 0))
);
CREATE TABLE "cart" (
	"total_amount" double precision NOT NULL,
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "cart_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"user_id" bigint CONSTRAINT "cart_user_id_key" UNIQUE
);
CREATE TABLE "cart_item" (
	"quantity" integer NOT NULL,
	"sub_total" double precision NOT NULL,
	"book_id" bigint,
	"cart_id" bigint,
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "cart_item_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	CONSTRAINT "cart_item_cart_id_book_id_key" UNIQUE("cart_id","book_id"),
	CONSTRAINT "cart_item_quantity_check" CHECK ((quantity >= 1))
);
CREATE TABLE "feedback" (
	"date_submitted" timestamp,
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "feedback_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"user_id" bigint,
	"feedback" varchar(2000) NOT NULL,
	"email" varchar(255) NOT NULL,
	"name" varchar(255) NOT NULL,
	"phone" varchar(255)
);
CREATE TABLE "purchase" (
	"total_amount" double precision NOT NULL,
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "purchase_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"purchase_date" timestamp,
	"user_id" bigint,
	"address" varchar(500) NOT NULL,
	"phone" varchar(255) NOT NULL
);
CREATE TABLE "purchase_item" (
	"price_at_purchase" double precision NOT NULL,
	"quantity" integer NOT NULL,
	"book_id" bigint,
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "purchase_item_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"purchase_id" bigint,
	CONSTRAINT "purchase_item_quantity_check" CHECK ((quantity >= 1))
);
CREATE TABLE "user_roles" (
	"user_id" bigint NOT NULL,
	"roles" varchar(255),
	CONSTRAINT "user_roles_user_id_roles_key" UNIQUE("user_id","roles"),
	CONSTRAINT "user_roles_roles_check" CHECK (((roles)::text = ANY ((ARRAY['CUSTOMER'::character varying, 'ADMIN'::character varying])::text[])))
);
CREATE TABLE "users" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "users_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"email" varchar(255) NOT NULL CONSTRAINT "users_email_key" UNIQUE,
	"name" varchar(255) NOT NULL,
	"password" varchar(255) NOT NULL,
	"username" varchar(255) NOT NULL CONSTRAINT "users_username_key" UNIQUE
);
CREATE UNIQUE INDEX "books_pkey" ON "books" ("id");
CREATE UNIQUE INDEX "cart_pkey" ON "cart" ("id");
CREATE UNIQUE INDEX "cart_user_id_key" ON "cart" ("user_id");
CREATE UNIQUE INDEX "cart_item_cart_id_book_id_key" ON "cart_item" ("cart_id","book_id");
CREATE UNIQUE INDEX "cart_item_pkey" ON "cart_item" ("id");
CREATE UNIQUE INDEX "feedback_pkey" ON "feedback" ("id");
CREATE UNIQUE INDEX "purchase_pkey" ON "purchase" ("id");
CREATE UNIQUE INDEX "purchase_item_pkey" ON "purchase_item" ("id");
CREATE UNIQUE INDEX "user_roles_user_id_roles_key" ON "user_roles" ("user_id","roles");
CREATE UNIQUE INDEX "users_email_key" ON "users" ("email");
CREATE UNIQUE INDEX "users_pkey" ON "users" ("id");
CREATE UNIQUE INDEX "users_username_key" ON "users" ("username");
ALTER TABLE "cart" ADD CONSTRAINT "fkg5uhi8vpsuy0lgloxk2h4w5o6" FOREIGN KEY ("user_id") REFERENCES "users"("id");
ALTER TABLE "cart_item" ADD CONSTRAINT "fk1uobyhgl1wvgt1jpccia8xxs3" FOREIGN KEY ("cart_id") REFERENCES "cart"("id");
ALTER TABLE "cart_item" ADD CONSTRAINT "fkb58e5ca5nwhh6hm3sboyggghe" FOREIGN KEY ("book_id") REFERENCES "books"("id");
ALTER TABLE "feedback" ADD CONSTRAINT "fkpwwmhguqianghvi1wohmtsm8l" FOREIGN KEY ("user_id") REFERENCES "users"("id");
ALTER TABLE "purchase" ADD CONSTRAINT "fkoj7ky1v8cf4ibkk0s7alikp52" FOREIGN KEY ("user_id") REFERENCES "users"("id");
ALTER TABLE "purchase_item" ADD CONSTRAINT "fk1mncc5yaore1sibgpj3jc4a7u" FOREIGN KEY ("purchase_id") REFERENCES "purchase"("id");
ALTER TABLE "purchase_item" ADD CONSTRAINT "fkehfi4uhgldwe56plh35a4elax" FOREIGN KEY ("book_id") REFERENCES "books"("id");
ALTER TABLE "user_roles" ADD CONSTRAINT "fkhfh9dx7w3ubf1co1vdev94g3f" FOREIGN KEY ("user_id") REFERENCES "users"("id");